import json
import requests

def process_log_file(log_file_path):
    http_status_counts = {}
    api_metadata = {}

    with open(log_file_path, 'r') as log_file:
        for line in iter(lambda: log_file.readline(), ''):
            status_code = int(line.split()[8].split(' ')[0])
            if status_code not in http_status_counts:
                http_status_counts[status_code] = 0
            http_status_counts[status_code] += 1

    def get_api_metadata(status_code):
        try:
            response = requests.get(f'https://api.example.com/status-codes/{status_code}')
            metadata = json.loads(response.content)
            return {**metadata, 'count': http_status_counts.get(status_code, 0)}
        except Exception as e:
            print(f'Error fetching metadata for status code {status_code}: {e}')
            return {}

    for status_code in http_status_counts:
        api_metadata[status_code] = get_api_metadata(status_code)

    return {**http_status_counts, **api_metadata}
