import os
import re
from collections import OrderedDict
from functools import lru_cache
from threading import Lock
from io import BytesIO

@lru_cache(maxsize=None)
def read_log_file(file_path):
    try:
        with open(file_path, 'rb') as file:
            return file.read()
    except Exception as e:
        print(f""Error reading log file {file_path}: {e}"")
        return None

def extract_timestamp(line):
    timestamp_pattern = re.compile(r'\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}')
    match = timestamp_pattern.search(line)
    if match:
        return match.group()
    return None

def sort_log_lines(lines, timestamp_format):
    sorted_lines = OrderedDict()
    for line in lines:
        timestamp = extract_timestamp(line.decode('utf-8').strip())
        if timestamp:
            try:
                ts = datetime.strptime(timestamp, timestamp_format)
                sorted_lines[ts] = line
            except ValueError as e:
                print(f""Invalid timestamp {timestamp}: {e}"")
    return list(sorted_lines.values())

def get_sequence_number(lines):
    last_line = lines[-1]
    sequence_pattern = re.compile(r'seq:(\d+)')
    match = sequence_pattern.search(last_line.decode('utf-8').strip())
    if match:
        return int(match.group(1))
    return None

@lru_cache(maxsize=None)
def sort_and_extract(file_path, timestamp_format):
    try:
        log_data = read_log_file(file_path)
        if not log_data:
            return None
        lines = [line.decode('utf-8').strip() for line in log_data.splitlines()]
        sorted_lines = sort_log_lines(lines, timestamp_format)
        sequence_number = get_sequence_number(sorted_lines)
        return sorted_lines, sequence_number
    except Exception as e:
        print(f""Error processing log file {file_path}: {e}"")
        return None

sort_lock = Lock()

@lru_cache(maxsize=None)
def sort_and_extract_with_file_lock(file_path, timestamp_format):
    with sort_lock:
        return sort_and_extract(file_path, timestamp_format)

def cache_sort_result(key, value):
    try:
        cache.set(key, value, 3600)  # cache for 1 hour
    except Exception as e:
        print(f""Error caching result {key}: {e}"")

@lru_cache(maxsize=None)
def get_cached_sorted_lines(file_path, timestamp_format):
    key = f""{file_path}:{timestamp_format}""
    sorted_lines = cache.get(key)
    if not sorted_lines:
        try:
            sorted_lines, _ = sort_and_extract_with_file_lock(file_path, timestamp_format)
            cache_sort_result(key, sorted_lines)
        except Exception as e:
            print(f""Error getting cached or calculating sorted lines for {file_path}: {e}"")
    return sorted_lines

def process_log_files(directory_path):
